import {calculate,monthly,clamp,weights} from './finance.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number.isFinite(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v):'Not available';
const shortDate=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No deadline';
const fmt=v=>Number.isFinite(v)?Math.round(v):'—';
const key='wealthloom.demo.v1';let base,data,id='H02',month='2026-11',expanded=false,state,commit;
const componentNames=['Savings goals','Cash buffer','Cash flow','Income diversity'];
const symbols=['◎','◒','↗','⑂'];
const methods=[
 ['Savings goals · 30%','Allocated savings ÷ selected goal target, capped at 100%. Allocations are existing cash earmarked for a purpose.'],
 ['Cash buffer · 30%','Available liquid savings ÷ (recurring monthly essential expenses × your buffer target), capped at 100%. One-time costs affect cash flow, not the recurring buffer denominator.'],
 ['Cash flow · 30%','Monthly surplus ÷ included cash inflows ÷ 20%, bounded to 0–100. A 20% surplus margin earns full points. This reference is a demo assumption.'],
 ['Income diversity · 10%','2 × (1 − sum of squared income-source shares), capped at 100%. Multiple payments from one source are grouped. Retirement withdrawals are excluded here; they remain in monthly cash inflows.']
];
$('accounts').insertAdjacentHTML('afterend','<section class="panel bills-panel" id="bills"><div class="panel-heading"><div><h2>Who covers what</h2><p>Shared responsibilities, without counting bills twice.</p></div></div><div id="billSplit"></div><details class="payment-history"><summary>Sample payment history · October 2026</summary><p class="fine-print">A small historical sample, not a complete ledger or proof of all bills paid. These payments are separate from the selected forecast month.</p><div id="paymentList"></div></details></section>');
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600);}
function persist(){try{localStorage.setItem(key,JSON.stringify(data));$('saveState').textContent='Saved in this browser';}catch{$('saveState').textContent='Session only · browser storage unavailable';}render();toast('Demo updated. Your financial picture has refreshed.');}
function modal(title,fields,save){$('editorTitle').textContent=title;$('editorFields').innerHTML=fields;$('formError').textContent='';commit=save;$('editor').showModal();}
function input(name,label,value,{type='number',min='0',step='0.01',help=''}={}){return `<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?`min="${min}" step="${step}"`:''} required>${help?`<small>${esc(help)}</small>`:''}</label>`;}
function select(name,label,value,choices){return `<label class="field"><span>${label}</span><select name="${name}">${choices.map(c=>`<option ${c===value?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;}
function amount(form,name){const v=Number(form.get(name));if(!Number.isFinite(v)||v<0||form.get(name)==='')throw Error('Enter a valid non-negative amount.');return v;}
function editExpense(index){const e=state.expenses[index];modal(e.description,input('amount',`Amount · ${e.frequency.toLowerCase()}`,e.amount)+select('kind','Spending type',e.essential_or_flexible,['Essential','Flexible','Unknown'])+`<p class="fine-print">Household total. Existing payer shares remain unchanged. This edits the plan, not a payment.</p>`,f=>{e.amount=amount(f,'amount');e.essential_or_flexible=f.get('kind');});}
function editAccount(index){const a=state.accounts[index];modal('Edit account balance',`<p>${esc(a.institution_name)} · ${esc(a.account_label)}</p>`+input('amount','Balance as of '+shortDate(a.as_of_date),a.balance)+select('available','Include in available cash?',a.available_for_runway,['Yes','No']),f=>{const value=amount(f,'amount');if(a.account_id===state.goal.allocation_account_id&&value<state.goal.allocated_amount)throw Error('This balance is below the amount allocated to your goal. Reduce the goal allocation first.');a.balance=value;a.available_for_runway=f.get('available');});}
function editGoal(){const g=state.goal;modal('Your goal, your pace.',input('name','Goal name',g.name,{type:'text'})+input('target','Target amount',g.target_amount,{min:'.01'})+input('allocated','Currently allocated from savings',g.allocated_amount)+input('monthly','Planned monthly contribution',g.planned_contribution)+input('deadline','Goal deadline',g.target_date,{type:'date'})+`<p class="fine-print">Changing an allocation does not change an account balance. Contributions are plans, not completed transfers.</p>`,f=>{const target=amount(f,'target'),allocated=amount(f,'allocated'),cash=state.accounts.find(a=>a.account_id===g.allocation_account_id)?.balance;if(target<=0)throw Error('Your goal target must be greater than zero.');if(allocated>cash)throw Error('Goal allocation cannot exceed the linked account balance.');const name=f.get('name').trim();if(!name)throw Error('Give your goal a name.');Object.assign(g,{name,target_amount:target,allocated_amount:allocated,planned_contribution:amount(f,'monthly'),target_date:f.get('deadline')});});}
function editIncome(){const rows=state.income.filter(r=>monthly(r,month)>0);modal('Plan your monthly inflows',rows.length?rows.map((r,i)=>input('income'+i,`${r.description} · ${r.frequency.toLowerCase()}`,r.net_amount,{help:r.income_kind==='asset_withdrawal'?'Planned drawdown of an existing asset.':'Net cash after deductions.'})).join(''):'<p>No income is scheduled for this month.</p>',f=>{const values=rows.map((r,i)=>amount(f,'income'+i));rows.forEach((r,i)=>r.net_amount=values[i]);});}
function render(){
 state=calculate(data,id,month);const s=state,p=data.records.people.find(p=>p.household_id===id&&p.relationship==='Self');
 $('personaName').textContent=`${p.display_name}, ${p.age}`;$('personaDetail').textContent=`${p.employment} · ${p.notes}`;$('avatar').textContent=p.display_name.split(' ').map(n=>n[0]).join('');
 $('score').textContent=s.score??'—';$('scoreRing').style.setProperty('--score',s.score??0);
 $('healthLabel').textContent=s.score===null?'More information needed':s.score>=80?'A strong foundation':s.score>=60?'A foundation to build on':s.score>=40?'Room to strengthen your picture':'A few areas deserve attention';
 $('healthMessage').textContent=s.margin<0?'Your planned spending exceeds this month’s inflows. Start with the gap, then work toward your goals.':s.components[0]<50?'Your cash flow gives you a starting point. Keep building toward the goals you’ve chosen.':'Your goals are taking shape. Explore the details to see what could make your picture stronger.';
 let nextTitle,nextText,nextHref;
 if(s.margin<0){nextTitle='Give your budget a little breathing room.';nextText=`Your plan has a ${money(-s.margin)} shortfall this month. Review flexible expenses before increasing savings contributions.`;nextHref='#budget';}
 else if(s.goal.planned_contribution>s.margin){nextTitle='Bring your savings plan into balance.';nextText=`Your ${money(s.goal.planned_contribution)} contribution plan exceeds this month’s ${money(s.margin)} surplus.`;nextHref='#goals';}
 else if(s.components[0]<100){nextTitle='Turn a good intention into steady progress.';nextText=`You have ${money(Math.max(0,s.goal.target_amount-s.goal.allocated_amount))} left toward your ${s.goal.name.toLowerCase()}. Review your monthly contribution and deadline.`;nextHref='#goals';}
 else{nextTitle='Make your next goal a little clearer.';nextText='Your selected goal is funded. Review your cash buffer and decide what matters next.';nextHref='#goals';}
 $('nextTitle').textContent=nextTitle;$('nextText').textContent=nextText;$('nextLink').href=nextHref;$('nextLink').innerHTML=`${nextHref==='#budget'?'Explore your budget':'Explore your savings goal'} <span>→</span>`;
 const stat=(label,value,note,negative=false)=>`<article class="stat ${negative?'negative':''}"><div class="label">${label}<span>↗</span></div><strong>${value}</strong><small>${note}</small></article>`;
 $('stats').innerHTML=stat('Available liquid savings',money(s.cash),'Opening snapshot · Nov 1, 2026')+stat('Monthly money in',money(s.inc),s.withdrawals?`${money(s.withdrawals)} is asset withdrawals`:'Net planned household inflows')+stat('Planned spending',money(s.spend),s.oneTime?`${money(s.oneTime)} includes one-time costs`:'For the selected forecast month')+stat(s.margin>=0?'Room in your budget':'Monthly shortfall',money(Math.abs(s.margin)),s.margin>=0?'Before planned savings transfers':'Expenses exceed planned inflows',s.margin<0);
 const notes=[`${money(s.goal.allocated_amount)} of ${money(s.goal.target_amount)} allocated`,`${s.coverage?.toFixed(1)??'—'} months of essentials · ${s.prefs.target_buffer_months}-month target`,s.inc>0?`${(s.margin/s.inc*100).toFixed(1)}% of monthly inflows remains`:'No inflows scheduled',s.largest===null?'No external income sources this month':`${Math.round(s.largest*100)}% from the largest source group`];
 $('components').innerHTML=componentNames.map((name,i)=>`<article class="component"><div class="component-top"><span class="component-icon">${symbols[i]}</span><span>${weights[i]*100}% OF SCORE</span></div><h3>${name}</h3><div class="component-value">${fmt(s.components[i])}<small> / 100</small></div><div class="progress"><span style="width:${s.components[i]??0}%"></span></div><p>${notes[i]}</p><button class="text-button component-help" data-index="${i}">Understand this measure ↗</button></article>`).join('');
 document.querySelectorAll('.component-help').forEach(b=>b.onclick=()=>showMethod(+b.dataset.index));
 $('cashSubtitle').textContent=new Date(month+'-01T12:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric'})+' · household plan';
 const max=Math.max(s.inc,s.spend,1);$('cashGraphic').innerHTML=[['In',s.inc],['Out',s.spend]].map(([label,v])=>`<div class="cash-bar-row"><span>${label}</span><div class="cash-bar"><i style="width:${v/max*100}%"></i></div><b>${money(v)}</b></div>`).join('');
 $('cashDetails').innerHTML=`<div class="cash-details ${s.margin<0?'negative':''}"><span>${s.margin>=0?'Planned surplus':'Planned shortfall'}</span><strong>${money(Math.abs(s.margin))}</strong></div>${s.withdrawals?`<p class="cash-note">Includes ${money(s.withdrawals)} of planned portfolio withdrawals. This is cash available to spend, not new earned income.</p>`:''}${s.hasUncertain?'<p class="cash-note">Income-source independence is unknown. Source diversity does not guarantee income stability.</p>':''}`;
 const expenseRows=s.expenses.map((e,i)=>({e,i,value:monthly(e,month)})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);
 $('expenseList').innerHTML=expenseRows.slice(0,expanded?undefined:5).map(({e,i,value})=>`<div class="expense-row"><span class="category-dot">${e.essential_or_flexible==='Flexible'?'◇':'▤'}</span><div class="expense-name">${esc(e.description)}<small>${esc(e.essential_or_flexible)} · ${e.frequency==='One-time'?'One-time':esc(e.frequency)}</small></div><span class="amount">${money(value)}</span><button class="edit-expense" aria-label="Edit ${esc(e.description)}" data-index="${i}">✎</button></div>`).join('');
 document.querySelectorAll('.edit-expense').forEach(b=>b.onclick=()=>editExpense(+b.dataset.index));$('allExpenses').textContent=expanded?'Show fewer expenses ↑':`View all ${expenseRows.length} expenses ↓`;
 const g=s.goal,pct=clamp(g.allocated_amount/g.target_amount*100),months=Math.max(0,(new Date(g.target_date)-new Date(month+'-01'))/86400000/30.4375),needed=months>0?Math.max(0,g.target_amount-g.allocated_amount)/months:null;
 $('goalContent').innerHTML=`<div class="goal-icon">◎</div><h3 class="goal-name">${esc(g.name)}</h3><p class="goal-date">Your target date · ${shortDate(g.target_date)}</p><div class="goal-numbers"><strong>${money(g.allocated_amount)}</strong><span>of ${money(g.target_amount)}</span></div><div class="progress"><span style="width:${pct}%"></span></div><div class="goal-meta"><span>${Math.round(pct)}% of your goal</span><span>${money(Math.max(0,g.target_amount-g.allocated_amount))} to go</span></div><div class="goal-contribution"><span>Planned monthly contribution</span><strong>${money(g.planned_contribution)} / mo</strong></div><p class="goal-warning">${s.margin<0?'A current cash-flow gap needs attention before adding contributions.':needed!==null&&needed>g.planned_contribution?`At a steady pace, about ${money(needed)} per month would close the gap by your deadline. This is a scenario, not a required contribution.`:g.allocated_amount>=g.target_amount?'You have allocated enough to reach this goal.':'Your selected contribution pace covers the remaining goal under a flat, no-interest assumption.'}</p>`;
 $('bufferValue').textContent=s.prefs.target_buffer_months+' months of essentials';
 const people=Object.fromEntries(data.records.people.map(p=>[p.person_id,p.display_name.split(' ')[0]]));
 $('accountList').innerHTML=s.accounts.map((a,i)=>`<article class="account"><div class="account-top"><span class="bank-icon"><img src="assets/${esc(a.institution_id)}.ico" alt="${esc(a.institution_name)} icon"><span class="fallback">${esc(a.institution_name.slice(0,2))}</span></span><div><h3>${esc(a.institution_name)}</h3><small>${esc(a.account_label)}</small></div></div><div class="account-balance">${money(a.balance)}</div><span class="subtle">${esc(a.owner_ids.split(',').map(x=>people[x]??x).join(' + '))} · ${shortDate(a.as_of_date)}</span><div class="account-bottom"><span>${a.available_for_runway==='Yes'?'Included in available cash':'Excluded from available cash'}</span><button class="text-button edit-account" data-index="${i}">Edit ↗</button></div></article>`).join('');
 document.querySelectorAll('.bank-icon img').forEach(img=>img.onerror=()=>{img.style.display='none';img.nextElementSibling.style.display='inline';});document.querySelectorAll('.edit-account').forEach(b=>b.onclick=()=>editAccount(+b.dataset.index));
 const allocations={};for(const e of s.expenses){const value=monthly(e,month);for(const n of [1,2]){const person=e['responsible_person_'+n],share=e['share_'+n];if(person&&Number.isFinite(share))allocations[person]=(allocations[person]??0)+value*share;}}
 $('billSplit').innerHTML=Object.entries(allocations).map(([person,value])=>`<div class="split-item"><span class="avatar">${esc(people[person]?.[0]??'?')}</span><div><strong>${esc(people[person]??person)}</strong><p>Planned responsibility · selected month</p></div><b>${money(value)}</b></div>`).join('');
 const payments=data.records.payments.filter(p=>p.household_id===id);$('paymentList').innerHTML=payments.map((p,i)=>{const expense=s.expenses.find(e=>e.expense_id===p.expense_id);return `<div class="expense-row"><div class="expense-name">${esc(expense?.description??'Expense')}<small>${shortDate(p.paid_date)} · paid by ${esc(people[p.paid_by]??p.paid_by)}</small></div><span class="amount">${money(p.amount)}</span><button class="edit-expense edit-payment" data-index="${i}" aria-label="Edit historical payment ${i+1}">✎</button></div>`;}).join('');
 document.querySelectorAll('.edit-payment').forEach(b=>b.onclick=()=>{const p=payments[+b.dataset.index];modal('Edit recorded payment',input('amount','Actual amount paid',p.amount)+`<p class="fine-print">Historical payment only. Forecast budget and score are unchanged by editing this history.</p>`,f=>{p.amount=amount(f,'amount');});});
 $('runwayContent').innerHTML=`<p>Opening available cash: <b>${money(s.cash)}</b>. Protected reserve: <b>${money(s.household.protected_reserve)}</b>. Essential-expense coverage: <b>${s.coverage?.toFixed(1)??'—'} months</b>.</p><p>${s.runway!==null?`At this month’s fixed deficit, cash above your reserve covers about <b>${s.runway.toFixed(1)} months</b>.`:'This month’s planned inflows cover spending, so there is no depletion runway under a fixed-month assumption.'} This is a snapshot sensitivity, not a dated forecast. It does not roll balances forward or account for later income changes.</p>`;
}
function showMethod(index=null){$('methodContent').innerHTML=(index===null?methods:methods.filter((_,i)=>i===index)).map(([title,text])=>`<div class="method-row"><strong>${title}</strong><p>${text}</p></div>`).join('');if(index===null)$('methodContent').innerHTML+='<p class="fine-print">Overall score = 30% goals + 30% cash buffer + 30% cash flow + 10% income diversity. Round once, after weighting. Prototype labels: 80+ strong foundation, 60–79 foundation to build on, 40–59 room to strengthen, below 40 areas to explore. These labels are authored heuristics.</p>';$('method').showModal();}
$('editorForm').onsubmit=e=>{e.preventDefault();try{commit(new FormData(e.target));$('editor').close();persist();}catch(error){$('formError').textContent=error.message;}};
$('closeEditor').onclick=$('cancelEditor').onclick=()=>$('editor').close();$('closeMethod').onclick=()=>$('method').close();
for(const id of ['methodButton','weightsButton','breakdownButton'])$(id).onclick=()=>showMethod();
$('incomeButton').onclick=editIncome;$('goalButton').onclick=editGoal;
$('bufferButton').onclick=()=>modal('Choose your cash buffer',input('months','Target months of essential expenses',state.prefs.target_buffer_months,{min:'0.1',step:'0.1'}),f=>{const v=amount(f,'months');if(v<=0||v>60)throw Error('Choose a target between 0.1 and 60 months.');state.prefs.target_buffer_months=v;});
$('allExpenses').onclick=()=>{expanded=!expanded;render();};
$('persona').onchange=e=>{id=e.target.value;expanded=false;render();};$('month').onchange=e=>{month=e.target.value;render();};
$('resetButton').onclick=()=>{for(const name of Object.keys(base.records)){data.records[name]=[...data.records[name].filter(r=>r.household_id!==id),...structuredClone(base.records[name].filter(r=>r.household_id===id))];}persist();};
document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');});
try{
 const response=await fetch('demo-data.json');if(!response.ok)throw Error('Demo data could not be loaded.');base=await response.json();data=structuredClone(base);
 try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.schema_version===base.schema_version)data=saved;}catch{}
 $('persona').innerHTML=base.records.household.map(h=>{const p=base.records.people.find(p=>p.household_id===h.household_id&&p.relationship==='Self');return `<option value="${h.household_id}">${esc(p.display_name)} · ${p.age}</option>`;}).join('');
 render();
}catch(error){$('healthMessage').textContent=error.message;$('healthLabel').textContent='Unable to load demo';}
